def generate(rng, n):
    if n <= 0:
        return [None]
    vals = [rng.randint(-100, 100) for _ in range(n)]
    root = TreeNode(vals[0])
    queue = [root]
    i = 1
    while queue and i < len(vals):
        curr = queue.pop(0)
        if i < len(vals):
            curr.left = TreeNode(vals[i])
            queue.append(curr.left)
            i += 1
        if i < len(vals):
            curr.right = TreeNode(vals[i])
            queue.append(curr.right)
            i += 1
    return [root]

def generate_worst(rng, n):
    return generate(rng, n)

